const sliceCommentKey='slice-comments-v1';
function commentsFor(id){const all=readStored(sliceCommentKey,{});return all&&Array.isArray(all[id])?all[id].filter(c=>c&&typeof c.text==='string'&&typeof c.id==='string'):[]}
const sliceDiscussion=document.createElement('section');sliceDiscussion.id='slice-discussion';sliceDiscussion.setAttribute('aria-label','Slice likes and comments');let discussionId=null;
function renderSliceDiscussion(){const w=works.find(x=>x.id===discussionId);if(!w)return;const comments=commentsFor(w.id);sliceDiscussion.innerHTML=`<div class="discussion-top"><h3>Comments <small>${comments.length}</small></h3><button data-like="${escapeHtml(w.id)}" class="detail-like ${likes.has(w.id)?'liked':''}" aria-pressed="${likes.has(w.id)}" aria-label="Like ${escapeHtml(w.title)}">${likes.has(w.id)?'♥':'♡'} ${w.likes+(likes.has(w.id)?1:0)}</button></div><form id="slice-comment-form"><label for="slice-comment-text">Talk about your experience</label><textarea id="slice-comment-text" required maxlength="1000" rows="2" placeholder="What did you discover? Any suggestions?"></textarea><div class="comment-submit-row"><small>Posted as You · Saved in this browser only</small><button class="dark" type="submit">Post comment</button></div><p id="comment-error" role="alert"></p></form><div class="comment-list">${comments.length?comments.map(c=>`<article class="comment-item"><span class="comment-avatar">You</span><div><div class="comment-meta"><strong>You</strong><time>${escapeHtml(updateDate(c.date))}</time></div><p>${escapeHtml(c.text)}</p></div></article>`).join(''):'<p class="comments-empty">No comments yet. Share the first discovery.</p>'}</div>`;sliceDiscussion.querySelector('form').onsubmit=e=>{e.preventDefault();const input=sliceDiscussion.querySelector('textarea'),text=input.value.trim();if(!text){sliceDiscussion.querySelector('#comment-error').textContent='Write a comment before posting.';return}const all=readStored(sliceCommentKey,{}),data=all&&typeof all==='object'&&!Array.isArray(all)?all:{};try{localStorage.setItem(sliceCommentKey,JSON.stringify({...data,[w.id]:[{id:crypto.randomUUID(),text,date:new Date().toISOString()},...commentsFor(w.id)]}));renderSliceDiscussion();toast('Comment saved locally.')}catch{sliceDiscussion.querySelector('#comment-error').textContent='Could not save your comment. Check browser storage.'}}}
function attachSliceDiscussion(id){discussionId=id;document.querySelector('#dialog-stage').after(sliceDiscussion);if(updateSection.isConnected)sliceDiscussion.after(updateSection);renderSliceDiscussion()}
const discussionOpenBefore=openWork;openWork=function(id,remix=false){discussionOpenBefore(id,remix);if(dialog.open&&!remix)attachSliceDiscussion(id);else sliceDiscussion.remove()};if(dialog.open&&!remixing)attachSliceDiscussion(activeId);
const persistedSliceLikes=readStored('slice-likes-v1',[]);if(Array.isArray(persistedSliceLikes))persistedSliceLikes.filter(id=>typeof id==='string').forEach(id=>likes.add(id));render();if(dialog.open&&discussionId)renderSliceDiscussion();document.addEventListener('click',e=>{const button=e.target.closest('[data-like]');if(!button)return;const id=button.dataset.like,w=works.find(x=>x.id===id);if(!w)return;document.querySelectorAll('[data-like]').forEach(b=>{if(b.dataset.like===id){b.classList.toggle('liked',likes.has(id));b.setAttribute('aria-pressed',String(likes.has(id)));b.textContent=(likes.has(id)?'♥':'♡')+' '+(w.likes+(likes.has(id)?1:0))}});try{localStorage.setItem('slice-likes-v1',JSON.stringify([...likes]))}catch{toast('Likes will only last for this session.')}});
